import { readFileSync, writeFileSync } from 'node:fs'
import { resolve } from 'node:path'
import { fileURLToPath, pathToFileURL } from 'node:url'
import openapiTS, { astToString } from 'openapi-typescript'

const OUTPUT = new URL('../src/api/codes.generated.ts', import.meta.url)

const HEADER = `// Generated by scripts/genCodes.ts from the Error.code enum of the API's OpenAPI document.
// Do not edit by hand: run \`bun run gen:codes <openapi.json>\` after the API adds a code.
`

export const renderCodes = (codes: readonly string[]): string =>
  `${HEADER}
export const API_ERROR_CODES = [
${codes.map((code) => `  '${code}',`).join('\n')}
] as const

export type ApiErrorCode = (typeof API_ERROR_CODES)[number]
`

const isRecord = (value: unknown): value is Record<string, unknown> =>
  typeof value === 'object' && value !== null && !Array.isArray(value)

/** Reads the Error.code enum out of an OpenAPI 3.x document held in memory. */
export const extractCodes = (document: unknown): string[] => {
  const components = isRecord(document) ? document.components : undefined
  const schemas = isRecord(components) ? components.schemas : undefined
  const errorSchema = isRecord(schemas) ? schemas.Error : undefined
  const properties = isRecord(errorSchema) ? errorSchema.properties : undefined
  const errorObject = isRecord(properties) ? properties.error : undefined
  const inner =
    isRecord(errorObject) && isRecord(errorObject.properties) ? errorObject : errorSchema
  const innerProperties = isRecord(inner) ? inner.properties : undefined
  const code = isRecord(innerProperties) ? innerProperties.code : undefined
  const values = isRecord(code) ? code.enum : undefined
  if (!Array.isArray(values) || !values.every((value) => typeof value === 'string')) {
    throw new Error('The document has no Error.code enum')
  }
  return values
}

const main = async (): Promise<void> => {
  const source = process.argv[2]
  if (!source) throw new Error('Usage: bun run gen:codes <path to a local openapi.json>')
  const document: unknown = JSON.parse(readFileSync(source, 'utf8'))
  const codes = extractCodes(document)
  // Run through openapi-typescript with enum values so a document it cannot read fails here,
  // not at the next API change.
  const ast = await openapiTS(pathToFileURL(source), { enumValues: true })
  const typed = astToString(ast)
  const missing = codes.filter((code) => !typed.includes(code))
  if (missing.length > 0) throw new Error(`openapi-typescript dropped: ${missing.join(', ')}`)
  writeFileSync(OUTPUT, renderCodes(codes))
}

if (resolve(process.argv[1] ?? '') === fileURLToPath(import.meta.url)) {
  main().catch((error: unknown) => {
    process.stderr.write(`${error instanceof Error ? error.message : String(error)}\n`)
    process.exitCode = 1
  })
}
